package com.testforge.testforge_backend.testsuite.controller;
import com.testforge.testforge_backend.testsuite.dto.*; import com.testforge.testforge_backend.testsuite.service.SuiteReportingService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/projects/{projectId}/reporting") public class SuiteReportingController {private final SuiteReportingService service;public SuiteReportingController(SuiteReportingService s){service=s;}@GetMapping("/test-suites")public List<SuiteReportSummary> summaries(@PathVariable String projectId){return service.summaries(projectId);}@GetMapping("/test-suites/{suiteId}/runs")public List<SuiteRunHistoryResponse> history(@PathVariable String projectId,@PathVariable Long suiteId){return service.history(projectId,suiteId);}@GetMapping("/suite-runs/{runId}")public SuiteRunResponse detail(@PathVariable String projectId,@PathVariable Long runId){return service.detail(projectId,runId);}}
